//! 🧪️ Captured opaque snapshots retain original registry and typed issuer through every source prefix.
use super::*;
use semio_framework_value::{retained_clone::{RetainedCloneSource,RetainedOwnedProjection},OwnedValueRetirementFactory};
struct OpaqueSnapshot{bytes:Vec<u8>}
#[derive(semio_framework_value::FactoryPayloadRetirement)]
struct OpaqueSnapshotIssuer;
impl ArtifactOwnedValueRetirementFactory<OpaqueSnapshot> for OpaqueSnapshotIssuer{
 fn retirement_birth_bytes(&self,value:&OpaqueSnapshot)->usize{ArtifactOwnedValueRetirementFactory::retirement_birth_bytes(&OwnedValueRetirementFactory::<Vec<u8>>::default(),&value.bytes)}
 fn retire_owned(&self,value:OpaqueSnapshot,grant:RetainedCloneGrant)->Result<(Box<dyn ErasedSnapshotRetirement>,RetainedCloneProgress),(ValueError,OpaqueSnapshot)>{ArtifactOwnedValueRetirementFactory::retire_owned(&OwnedValueRetirementFactory::<Vec<u8>>::default(),value.bytes,grant).map_err(|(error,bytes)|(error,OpaqueSnapshot{bytes}))}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observe<T>(call:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(call);assert!(!heap.overflowed);(value,heap.requested_bytes,heap.released_bytes)}
fn receipt(p:RetainedCloneProgress,g:RetainedCloneGrant,born:usize,released:usize){assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));}
fn close_projection(value:&mut RetainedOwnedProjection<OpaqueSnapshot>){for _ in 0..10000{if value.terminal_is_empty(){return;}let g=grant(value.close_demand(4096).unwrap());let(step,born,released)=observe(||value.close_step(g).unwrap());receipt(step.progress(),g,born,released);}panic!("captured snapshot projection did not close");}
#[test]
fn captured_snapshot_source_uses_original_registry_and_installed_opaque_issuer(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 let issuer:Arc<dyn ArtifactOwnedValueRetirementFactory<OpaqueSnapshot>>=Arc::new(OpaqueSnapshotIssuer);
 for law in corpus["cases"].as_array().unwrap(){for cancel_at in 0..3{
  let mut registry=Some(super::super::SnapshotReadRegistryHandle::new());let bytes=law["bytes"].as_array().unwrap().iter().map(|byte|byte.as_u64().unwrap()as u8).collect();let root=Arc::new(OpaqueSnapshot{bytes});let pointer=Arc::as_ptr(&root);let original=registry.as_ref().unwrap().try_issue(Arc::clone(&root)).unwrap_or_else(|_|panic!("captured original issue"));let(index,generation)=(original.index,original.generation);let mut read=Some(SnapshotRead::new(root,original));
  let demand=CapturedSnapshotSource::<OpaqueSnapshot>::constructor_demand();let g=grant(demand);
  for axis in 0..3{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1};let(result,born,released)=observe(||CapturedSnapshotSource::admit(&mut read,&issuer,denied).unwrap());assert!(result.is_none());assert_eq!((born,released),(0,0));assert_eq!(read.as_ref().unwrap().get()as*const _,pointer);assert!(registry.as_ref().unwrap().contains(index,generation));}
  let mut authority=if cancel_at==0{None}else{let(result,born,released)=observe(||CapturedSnapshotSource::admit(&mut read,&issuer,g).unwrap());let(value,p)=result.unwrap();receipt(p,g,born,released);assert_eq!(value.get()as*const _,pointer);Some(value)};
  let mut source=if cancel_at==2{type Source=RetainedCloneSource<OpaqueSnapshot,CapturedSnapshotSource<OpaqueSnapshot>>;let g=grant(RetirementDemand{copy_bytes:Source::constructor_copy_bytes(),capacity_bytes:Source::constructor_capacity_bytes::<()>(),depth:1,..Default::default()});let(result,born,released)=observe(||Source::admit_borrowed(authority.take().unwrap(),CapturedSnapshotSource::get,g));let(value,p)=result.map_err(|(error,_)|error).unwrap();receipt(p,g,born,released);assert_eq!(value.borrow().get()as*const _,pointer);Some(value)}else{None};
  let mut projection=if source.is_some()&&law["projectionHeld"]==true{let g=grant(RetainedOwnedProjection::<OpaqueSnapshot>::constructor_demand());let((value,p),born,released)=observe(||source.as_ref().unwrap().retain_original(g).unwrap());receipt(p,g,born,released);assert_eq!(serde_json::to_value(&value.borrow().unwrap().get().bytes).unwrap(),law["expected"]);Some(value)}else{None};
  if cancel_at==0{let(value,_)=CapturedSnapshotSource::admit(&mut read,&issuer,g).unwrap().unwrap();authority=Some(value);}assert!(read.is_none());if law["registryHeld"]==false{drop(registry.take());}
  let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();let mut completed=false;
  for turn in 0..corpus["maximumTurns"].as_u64().unwrap(){if turn==3{if let Some(value)=projection.as_mut(){close_projection(value);}projection=None;}
   let d=if let Some(value)=source.as_ref(){value.next_close_demand(4096).unwrap()}else{close.next_owner_demands::<CapturedSnapshotSource<OpaqueSnapshot>>(authority.is_some(),&None,4096).unwrap()};let g=grant(d);
   for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};let(result,born,released)=observe(||if let Some(value)=source.as_mut(){value.close_step(denied)}else{close.begin_granted(&mut authority,denied).and_then(|step|step.map_or_else(||close.step_granted(denied),Ok))});match result{Ok(step)=>assert_eq!(step.progress(),RetainedCloneProgress::default()),Err(error)=>assert_eq!(error.retained_progress(),RetainedCloneProgress::default())};assert_eq!((born,released),(0,0));}
   let(step,born,released)=observe(||if let Some(value)=source.as_mut(){value.close_step(g).unwrap()}else if let Some(step)=close.begin_granted(&mut authority,g).unwrap(){step}else{close.step_granted(g).unwrap()});receipt(step.progress(),g,born,released);
   if source.as_ref().is_some_and(|value|value.terminal_is_empty()){source=None;}if source.is_none()&&authority.is_none()&&close.is_empty()&&projection.is_none(){completed=true;break;}
  }assert!(completed&&projection.is_none());
  if let Some(registry)=registry.take(){assert!(registry.contains(index,generation));let mut active:Option<Box<dyn ErasedSnapshotRetirement>>=None;for _ in 0..10000{if registry.terminal_is_empty()&&active.is_none(){break;}let d=if let Some(active)=active.as_ref(){super::super::artifact_retirement_box_demands(active,4096).unwrap()}else{registry.returned_admission_demands::<OpaqueSnapshot>(|_|RetirementDemand{capacity_bytes:semio_framework_value_factory::shared::FactorySharedRetirement::<OpaqueSnapshot>::constructor_capacity_bytes(),depth:1,..Default::default()}).unwrap()};let g=grant(d);let(step,born,released)=observe(||super::super::advance_returned_snapshot_read(&registry,&mut active,&issuer,g).unwrap());receipt(step.progress(),g,born,released);}assert!(registry.terminal_is_empty());crate::presence_test_retirement::finish_registry(registry);}
 }}let mut factory=FactoryAuthority::new(issuer);for _ in 0..10000{if factory.terminal_is_empty(){break;}let g=grant(factory.demands(4096).unwrap());let(step,born,released)=observe(||factory.step(g).unwrap());receipt(step.progress(),g,born,released);}assert!(factory.terminal_is_empty());println!("[DEBUG] captured opaque snapshot source 4 registry/projection cases x 3 original birth prefixes");
}
